<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ClubController extends Controller
{
 private function schoolId(): int { return (int) session('school_id', 1); }
 public function dashboard() { $q=DB::table('clubs')->where('school_id',$this->schoolId()); return view('clubs.dashboard',['total'=>(clone $q)->count(),'active'=>(clone $q)->where('status','active')->count(),'recent'=>(clone $q)->latest()->limit(6)->get()]); }
 public function index(Request $request) { $q=DB::table('clubs')->where('school_id',$this->schoolId()); if($request->filled('search')) $q->where(function($x) use($request) { $x->where('name','like','%'.$request->search.'%'); }); if($request->filled('status')) $q->where('status',$request->status); $items=$q->latest()->paginate(15)->withQueryString(); return view('clubs.index',compact('items')); }
 public function create() { $campuses=DB::table('campuses')->where('school_id',$this->schoolId())->orderBy('name')->get(); $staff=DB::table('staff_profiles')->where('school_id',$this->schoolId())->whereNull('deleted_at')->orderBy('first_name')->get(); return view('clubs.create',compact('campuses','staff')); }
 public function store(Request $request) { $data=$request->validate(['name'=>'required|string|max:255','category'=>'nullable|string|max:80','description'=>'nullable|string','campus_id'=>'nullable|integer','faculty_coordinator_id'=>'nullable|integer','founded_on'=>'nullable|date','status'=>'required|in:active,inactive']); $data['school_id']=$schoolId; DB::table('clubs')->insert($data+['created_at'=>now(),'updated_at'=>now()]); return redirect()->route('clubs.index')->with('success','Record created successfully.'); }
 public function show(int $id) { $item=DB::table('clubs')->where('school_id',$this->schoolId())->find($id); abort_unless($item,404); return view('clubs.show',compact('item')); }
 public function edit(int $id) { $item=DB::table('clubs')->where('school_id',$this->schoolId())->find($id); abort_unless($item,404); $campuses=DB::table('campuses')->where('school_id',$this->schoolId())->orderBy('name')->get(); $staff=DB::table('staff_profiles')->where('school_id',$this->schoolId())->whereNull('deleted_at')->orderBy('first_name')->get(); return view('clubs.edit',compact('item','campuses','staff')); }
 public function update(Request $request,int $id) { $item=DB::table('clubs')->where('school_id',$this->schoolId())->find($id); abort_unless($item,404); $data=$request->validate(['name'=>'required|string|max:255','category'=>'nullable|string|max:80','description'=>'nullable|string','campus_id'=>'nullable|integer','faculty_coordinator_id'=>'nullable|integer','founded_on'=>'nullable|date','status'=>'required|in:active,inactive']); $data['school_id']=$schoolId; $data['updated_at']=now(); DB::table('clubs')->where('id',$id)->where('school_id',$this->schoolId())->update($data); return redirect()->route('clubs.show',$id)->with('success','Record updated successfully.'); }
 public function destroy(int $id) { $deleted=DB::table('clubs')->where('school_id',$this->schoolId())->where('id',$id)->delete(); abort_unless($deleted,404); return redirect()->route('clubs.index')->with('success','Record deleted successfully.'); }
}
